const items = $input.all();
const responses = items.map((item, i) => {
  const d = item.json;
  return `[${i+1}] Department: ${d.Department || d.department || 'N/A'} | Rating: ${d.Rating || d.rating || d.Score || 'N/A'} | Feedback: ${d.Feedback || d.feedback || d.Comments || d.comments || ''}`;
}).join('\n');
return [{ json: { surveyData: responses, responseCount: items.length, month: new Date().toISOString().substring(0, 7) } }];

values.content:
=You are an HR analytics expert. Analyze {{ $json.responseCount }} employee survey responses and provide insights.

Extract:
1. Major themes (positive and negative)
2. Sentiment breakdown by department (if data available)
3. Key action items for management
4. Employee satisfaction trends
5. Risk areas requiring immediate attention

Return JSON:
{
  "overall_sentiment": "positive/negative/mixed",
  "satisfaction_score": 7.5,
  "themes": [
    {"theme": "...", "sentiment": "positive/negative", "frequency": "high/medium/low", "sample_quotes": ["..."]}
  ],
  "department_insights": [
    {"department": "...", "sentiment": "...", "key_issues": ["..."]}
  ],
  "action_items": [
    {"priority": "high/medium/low", "action": "...", "department": "all/specific", "timeline": "immediate/30days/90days"}
  ],
  "risk_areas": ["..."],
  "positive_highlights": ["..."],
  "executive_summary": "3-4 sentence summary for leadership"
}

Survey Responses:
{{ $json.surveyData }}

parameters.jsCode:
const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { executive_summary: aiResponse, satisfaction_score: 0, themes: [], action_items: [], risk_areas: [] };
}

const themesSummary = (parsed.themes || []).map(t => `[${t.sentiment}] ${t.theme} (${t.frequency} frequency)`).join('\n');
const actionsSummary = (parsed.action_items || []).map(a => `[${a.priority}] ${a.action} — ${a.department} (${a.timeline})`).join('\n');

return [{
  json: {
    month: items[0].json.month || new Date().toISOString().substring(0, 7),
    responseCount: items[0].json.responseCount || 0,
    overallSentiment: parsed.overall_sentiment || '',
    satisfactionScore: parsed.satisfaction_score || 0,
    themes: themesSummary,
    actionItems: actionsSummary,
    riskAreas: Array.isArray(parsed.risk_areas) ? parsed.risk_areas.join('; ') : '',
    positiveHighlights: Array.isArray(parsed.positive_highlights) ? parsed.positive_highlights.join('; ') : '',
    executiveSummary: parsed.executive_summary || ''
  }
}];
